import json, os
state = {"visits": 0}
if os.path.exists("story-save.json"):
    try:
        with open("story-save.json", encoding="utf-8") as file:
            loaded = json.load(file)
        visits = loaded.get("visits")
        if isinstance(visits, int) and 0 <= visits <= 100000:
            state["visits"] = visits
        else:
            print("存档内容不合规则，开始新故事")
    except (ValueError, AttributeError):
        print("存档无法读取，开始新故事")
print("恢复次数：", state["visits"])
def explore(route):
    if route == "garden":
        return "花园结局"
    if route == "sea":
        return "海边结局"
    return None
while True:
    route = input("garden/sea，exit退出：")
    if route == "exit":
        break
    result = explore(route)
    if result is None:
        print("请重新选择")
        continue
    state["visits"] += 1
    print(result)
with open("story-save.json", "w", encoding="utf-8") as file:
    json.dump(state, file, ensure_ascii=False)
print("总次数：", state["visits"])
print("请导出存档，下次可以导入恢复")
